const PizzaSliceIcon: React.FC<{ filled?: boolean; className?: string }> = ({ filled, className }) => (
  <SvgBase className={className}>
    <path d="M6 8.5c8-2.7 16-2.7 24 0L18 31 6 8.5Z" fill={filled ? 'currentColor' : 'none'} stroke="currentColor" strokeWidth="1.8" strokeLinejoin="round" />
    <path d="M7.4 11c7-2.1 14.1-2.1 21.2 0" stroke={filled ? 'white' : 'currentColor'} strokeWidth="2.6" strokeLinecap="round" />
    <circle cx="14.2" cy="16.2" r="2" fill={filled ? 'white' : 'currentColor'} opacity=".92" />
    <circle cx="21.6" cy="19.2" r="2" fill={filled ? 'white' : 'currentColor'} opacity=".92" />
  </SvgBase>
);

const SPRITE_POSITIONS: Partial<Record<RatingIconType, [number, number]>> = {
  coffee:[0,0], hamburger:[1,0], fries:[2,0], pizza:[3,0], coxinha:[4,0], cake:[5,0],
  donut:[0,1], icecream:[1,1], chicken:[2,1], beef:[3,1], sandwich:[4,1], hotdog:[5,1],
  croissant:[0,2], cupcake:[1,2], cookie:[2,2], shrimp:[3,2], fish:[4,2], pasta:[5,2],
  drink:[0,3], beer:[1,3], meal:[2,3], salad:[3,3], taco:[4,3], skewer:[5,3],
};

const PhotoStyleFoodIcon: React.FC<{ type: RatingIconType; className?: string }> = ({ type, className='w-8 h-8' }) => {
  const pos = SPRITE_POSITIONS[type];
  if (!pos) return null;

  const [x, y] = pos;

  // Cada ícone ocupa uma célula de uma grade 6 x 4.
  // O recorte é feito com overflow em vez de background-position,
  // evitando que partes do ícone vizinho apareçam.
  // A imagem é ampliada um pouco para o desenho ocupar o mesmo
  // enquadramento visual do BrigadeiroIcon.
  return (
    <span
      className={`relative inline-block overflow-hidden align-middle ${className}`}
      aria-hidden="true"
    >
      <img
        src={foodIconsSprite}
        alt=""
        draggable={false}
        className="pointer-events-none absolute max-w-none select-none"
        style={{
          width: '600%',
          height: '400%',
          left: `${-x * 100}%`,
          top: `${-y * 100}%`,
          objectFit: 'fill',
        }}
      />
    </span>
  );
};

export const RatingChoiceIcon: React.FC<RatingChoiceIconProps> = ({ type='coxinha', filled=false, className='w-8 h-8' }) => {
  if(type==='star') return <Star className={className} fill={filled?'currentColor':'none'} strokeWidth={1.9}/>;
  if(type==='brigadeiro') return <BrigadeiroIcon filled={filled} className={className}/>;
  if(SPRITE_POSITIONS[type]) return <PhotoStyleFoodIcon type={type} className={className}/>;
  return <CoxinhaIcon filled={filled} className={className}/>;
};
